#include <iostream>
#include <map>
#include <string>

int main() {
    std::map<std::string, int> freq;
    std::string word;
    while (std::cin >> word) {
        freq[word]++;
    }
    for (auto const& [key, val] : freq) {
        std::cout << key << ": " << val << std::endl;
    }
    return 0;
}
